import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"更新部件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"拉取部件更新","slug":"拉取部件更新","link":"#拉取部件更新","children":[{"level":3,"title":"更新定义","slug":"更新定义","link":"#更新定义","children":[]},{"level":3,"title":"附加和前置内容","slug":"附加和前置内容","link":"#附加和前置内容","children":[]}]},{"level":2,"title":"推送部件更新","slug":"推送部件更新","link":"#推送部件更新","children":[]},{"level":2,"title":"将变量传递给 部件","slug":"将变量传递给-部件","link":"#将变量传递给-部件","children":[]}],"relativePath":"2.x/zh-cn/ajax/update-partials.md","filePath":"2.x/zh-cn/ajax/update-partials.md"}'),r={name:"2.x/zh-cn/ajax/update-partials.md"};function u(d,a,g,k,m,h){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"更新部件",-1)),n(e),a[1]||(a[1]=i(`<p>当处理程序执行时，它可以准备在页面上更新的部件，通过推送拉取，可以用一些提供的变量呈现。</p><h2 id="拉取部件更新"><a href="#拉取部件更新" class="header-anchor">#</a> 拉取部件更新</h2><p>客户端浏览器在执行 AJAX 请求时可能会请求从服务器更新部件内容，这被认为是<em>拉取内容更新</em>。 以下代码在调用 <code>onRefreshTime</code> <a href="./../ajax/handlers.html">事件处理程序</a> 后呈现页面上 <code>#myDiv</code> 元素内的 <strong>mytime</strong> 部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./../ajax/attributes-api.html">数据属性 API</a> 使用 <code>data-request-update</code> 属性。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mytime: &#39;#myDiv&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./../ajax/javascript-api.html">JavaScript API</a> 使用 <code>update</code> 配置选项：</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token comment">// JavaScript API</span>
$<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onRefreshTime&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">mytime</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="更新定义"><a href="#更新定义" class="header-anchor">#</a> 更新定义</h3><p>应更新内容的定义被指定为类似 JSON 的对象，其中：</p><ul><li>左侧(键)是<strong>部件名称</strong></li><li>右侧(值)是要更新的<strong>目标元素</strong></li></ul><p>以下将请求使用 <strong>mypartial</strong> 内容更新 <code>#myDiv</code> 元素。</p><div class="language- extra-class"><pre class="language-text"><code>mypartial: &#39;#myDiv&#39;
</code></pre></div><p>多个部件用逗号分隔。</p><div class="language- extra-class"><pre class="language-text"><code>firstpartial: &#39;#myDiv&#39;, secondpartial: &#39;#otherDiv&#39;
</code></pre></div><p>如果部件名称包含斜杠或破折号，则&quot;引用&quot;左侧很重要。</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/mypartial&#39;: &#39;#myDiv&#39;, &#39;my-partial&#39;: &#39;#myDiv&#39;
</code></pre></div><p>目标元素将始终位于右侧，因为它也可以是 JavaScript 中的 HTML 元素。</p><div class="language- extra-class"><pre class="language-text"><code>mypartial: document.getElementById(&#39;myDiv&#39;)
</code></pre></div><h3 id="附加和前置内容"><a href="#附加和前置内容" class="header-anchor">#</a> 附加和前置内容</h3><p>如果选择器字符串前面带有 <code>@</code> 符号，则从服务器接收到的内容将附加到元素中，而不是替换现有内容。</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/append&#39;: &#39;@#myDiv&#39;
</code></pre></div><p>如果选择器字符串前面带有<code>^</code> 符号，则内容将被添加到前面。</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/append&#39;: &#39;^#myDiv&#39;
</code></pre></div><h2 id="推送部件更新"><a href="#推送部件更新" class="header-anchor">#</a> 推送部件更新</h2><p>相比之下，<a href="./../ajax/handlers.html">AJAX 处理程序</a> 可以<em>将内容更新</em>从服务器端推送到客户端浏览器。 要推送更新，处理程序返回一个数组，其中键是要更新的 HTML 元素(使用简单的 CSS 选择器)，值是要更新的内容。</p><p>下面的示例将使用在部件 <strong>mypartial</strong> 中找到的内容更新页面上具有 id <strong>myDiv</strong> 的元素。 <code>onRefreshTime</code> 处理程序调用 <code>renderPartial</code> 方法来渲染 PHP 中的部件内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRefreshTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#myDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypartial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：键名必须以标识符<code>#</code> 或类<code>.</code> 字符开头才能触发内容更新。</p></blockquote><h2 id="将变量传递给-部件"><a href="#将变量传递给-部件" class="header-anchor">#</a> 将变量传递给 部件</h2><p>根据执行上下文，<a href="./../ajax/handlers.html">AJAX 事件处理程序</a> 使变量可用于不同部件。</p><ul><li>在页面或布局 <a href="./../cms/themes.html#oc-php-section">PHP 部分</a> 中使用 <code>$this[]</code>。</li><li>在 <a href="./../plugin/components.html#oc-ajax-handlers">组件类</a> 中使用 <code>$this-&gt;page[]</code>。</li><li>在<a href="./../backend/controllers-ajax.html#oc-using-ajax-handlers">后端区域</a>中使用<code>$this-&gt;vars[]</code>。</li></ul><p>这些示例将为每个上下文的部件提供 <strong>result</strong> 变量：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 从页面或布局 PHP 代码部分</span>
<span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// 从组件类</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// 从后端控制器或小部件</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>然后可以在部件中使用 Twig 访问此值：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Hello world! --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,36))])}const x=p(r,[["render",u]]);export{f as __pageData,x as default};
